#include "stdlib/stats/base/ndarray/smeanpw.h"
#include "stdlib/stats/strided/smeanpw.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/base/numel_dimension.h"
#include "stdlib/ndarray/base/stride.h"
#include "stdlib/ndarray/base/offset.h"
#include "stdlib/ndarray/base/data_buffer.h"
#include <stdint.h>

/**
* Computes the arithmetic mean of a one-dimensional single-precision floating-point ndarray using pairwise summation.
*
* @param arrays   array containing a single input ndarray
* @return         output value
*/
float stdlib_stats_smeanpw( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	
	const int64_t N = stdlib_ndarray_numel_dimension( x, 0 );
	const int64_t stride = stdlib_ndarray_stride( x, 0 );
	const int64_t offset = stdlib_ndarray_offset( x );
	uint8_t *data = stdlib_ndarray_data_buffer( x );
	
	return stdlib_strided_smeanpw_ndarray( N, (float *)data, stride, offset );
}
